/**
 * The Astryx themes a person can pick. Kept free of the theme modules themselves (their CSS and built objects live
 * in `src/astryx-themes.ts`, generated by `astryx theme add`), so the inline boot script and tests can use the list
 * without pulling in any stylesheet. `themes.test.ts` checks this list against the generated module.
 */
export const THEME_SLUGS = ["neutral", "butter", "chocolate", "matcha", "stone", "gothic", "y2k"] as const
export type ThemeSlug = (typeof THEME_SLUGS)[number]

export const DEFAULT_THEME: ThemeSlug = "neutral"

/** Themes that only exist in dark. The colour-scheme control is locked to dark while one is active. */
export const DARK_ONLY_THEMES: ReadonlySet<ThemeSlug> = new Set<ThemeSlug>(["gothic"])

export const THEME_LABELS: Record<ThemeSlug, { label: string; description: string }> = {
  neutral: { label: "Neutral", description: "Muted and minimal" },
  butter: { label: "Butter", description: "Golden surfaces, blue accents" },
  chocolate: { label: "Chocolate", description: "Warm browns and beige" },
  matcha: { label: "Matcha", description: "Earthy greens" },
  stone: { label: "Stone", description: "Warm stone and slate" },
  gothic: { label: "Gothic", description: "Dark only, ink and noir" },
  y2k: { label: "Y2K", description: "Playful periwinkle pop" },
}

export function isThemeSlug(value: unknown): value is ThemeSlug {
  return typeof value === "string" && (THEME_SLUGS as readonly string[]).includes(value)
}

/** The person-facing colour scheme preference. `system` follows the device. */
export type ColorSchemePref = "system" | "light" | "dark"
export type ResolvedScheme = "light" | "dark"
